fn arccos(x: Vec<i8>) -> Vec<i8> {
    // Prepare an output vector with the same length as the input.
    let mut result = Vec::with_capacity(x.len());

    for &v in &x {
        // Map according to the specification:
        //  • input  1 maps to 0
        //  • input -1 maps to 3
        //  • input  0 can map to any value in [0,3]; here we choose 2
        let m = match v {
            1  => 0,
            -1 => 3,
            0  => 2,
            _  => unreachable!("Input values must be in [-1, 0, 1]"),
        };
        result.push(m);
    }

    result
}